<?php
if (!defined('ABSPATH')) { exit; }

function rallyop_safety_install() {
    global $wpdb;
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    $charset = $wpdb->get_charset_collate();
    $audit = $wpdb->prefix . 'rallyop_game_audit';
    $trash = $wpdb->prefix . 'rallyop_game_trash';
    dbDelta("CREATE TABLE $audit (id bigint unsigned NOT NULL AUTO_INCREMENT,group_id bigint unsigned NOT NULL,game_id bigint unsigned NOT NULL,action varchar(20) NOT NULL,snapshot longtext NOT NULL,user_id bigint unsigned NOT NULL,created_at datetime NOT NULL,PRIMARY KEY(id),KEY group_time(group_id,created_at)) $charset;");
    dbDelta("CREATE TABLE $trash (id bigint unsigned NOT NULL AUTO_INCREMENT,group_id bigint unsigned NOT NULL,game_id bigint unsigned NOT NULL,snapshot longtext NOT NULL,deleted_by bigint unsigned NOT NULL,deleted_at datetime NOT NULL,restored_at datetime NULL,PRIMARY KEY(id),KEY group_restore(group_id,restored_at)) $charset;");
    $seasons = $wpdb->prefix . 'rallyop_seasons';
    $columns = $wpdb->get_col("DESCRIBE $seasons");
    if ($columns && !in_array('planned_ends_on', $columns, true)) { $wpdb->query("ALTER TABLE $seasons ADD planned_ends_on date NULL AFTER starts_on"); }
    if ($columns && !in_array('carryover', $columns, true)) { $wpdb->query("ALTER TABLE $seasons ADD carryover tinyint(1) unsigned NOT NULL DEFAULT 1 AFTER champion"); }
    update_option('rallyop_safety_db_version', '1.0.0');
}
add_action('init', function(){ if (get_option('rallyop_safety_db_version') !== '1.0.0') rallyop_safety_install(); }, 5);

function rallyop_audit_game($action, $game, $after = null) {
    if (!$game) return;
    global $wpdb;
    $wpdb->insert($wpdb->prefix.'rallyop_game_audit', ['group_id'=>(int)$game->group_id,'game_id'=>(int)$game->id,'action'=>sanitize_key($action),'snapshot'=>wp_json_encode(['before'=>$game,'after'=>$after]),'user_id'=>get_current_user_id(),'created_at'=>current_time('mysql')], ['%d','%d','%s','%s','%d','%s']);
}
function rallyop_trash_game($game) {
    if (!$game) return;
    global $wpdb;
    $wpdb->insert($wpdb->prefix.'rallyop_game_trash', ['group_id'=>(int)$game->group_id,'game_id'=>(int)$game->id,'snapshot'=>wp_json_encode($game),'deleted_by'=>get_current_user_id(),'deleted_at'=>current_time('mysql')], ['%d','%d','%s','%d','%s']);
    rallyop_audit_game('delete', $game);
}
function rallyop_is_duplicate_game($group_id, $ids, $score_a, $score_b, $played_at) {
    global $wpdb; $tables=rop_tables();
    $date = sanitize_text_field($played_at ?: wp_date('Y-m-d'));
    $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$tables['games']} WHERE group_id=%d AND DATE(played_at)=DATE(%s) ORDER BY id DESC LIMIT 50",$group_id,$date));
    $a=$ids[0].','.$ids[1]; $ar=$ids[1].','.$ids[0]; $b=$ids[2].','.$ids[3]; $br=$ids[3].','.$ids[2];
    foreach($rows as $g){$ga=$g->team_a1.','.$g->team_a2;$gb=$g->team_b1.','.$g->team_b2;if((in_array($ga,[$a,$ar],true)&&in_array($gb,[$b,$br],true)&&(int)$g->score_a===$score_a&&(int)$g->score_b===$score_b)||(in_array($ga,[$b,$br],true)&&in_array($gb,[$a,$ar],true)&&(int)$g->score_a===$score_b&&(int)$g->score_b===$score_a))return true;}return false;
}

add_action('admin_post_rallyop_restore_game', function(){
    if(!is_user_logged_in())auth_redirect();$trash_id=absint($_POST['trash_id']??0);check_admin_referer('rallyop_restore_game_'.$trash_id);global $wpdb;$table=$wpdb->prefix.'rallyop_game_trash';$item=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d AND restored_at IS NULL",$trash_id));if(!$item)wp_die('Recovery item not found.',404);$member=rop_member((int)$item->group_id);if(!$member||$member->role!=='owner')wp_die('Only the group owner can restore games.',403);$data=json_decode($item->snapshot,true);$games=rop_tables()['games'];$existing=$wpdb->get_var($wpdb->prepare("SELECT id FROM $games WHERE id=%d",$item->game_id));if($existing)unset($data['id']);$wpdb->insert($games,$data);$wpdb->update($table,['restored_at'=>current_time('mysql')],['id'=>$trash_id],['%s'],['%d']);rallyop_audit_game('restore',(object)$data);wp_safe_redirect(add_query_arg(['group'=>$item->group_id,'rop_notice'=>'Game restored.'],home_url('/')).'#rallyop-performance');exit;
});

add_action('admin_post_rallyop_download_backup', function(){
    if(!is_user_logged_in())auth_redirect();$group_id=absint($_GET['group_id']??0);check_admin_referer('rallyop_backup_'.$group_id);$member=rop_member($group_id);if(!$member||$member->role!=='owner')wp_die('Only the group owner can download backups.',403);global $wpdb;$games=rop_tables()['games'];$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM $games WHERE group_id=%d ORDER BY played_at,id",$group_id),ARRAY_A);nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=rallyop-group-'.$group_id.'-backup-'.wp_date('Y-m-d').'.csv');$out=fopen('php://output','w');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $row)fputcsv($out,$row);}fclose($out);exit;
});

add_action('wp_footer', function(){
    if(!is_front_page()||!is_user_logged_in())return;$group_id=max(1,absint($_GET['group']??1));$member=rop_member($group_id);if(!$member||$member->role!=='owner')return;global $wpdb;$trash=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rallyop_game_trash WHERE group_id=%d AND restored_at IS NULL ORDER BY deleted_at DESC LIMIT 8",$group_id));$audit=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rallyop_game_audit WHERE group_id=%d ORDER BY created_at DESC LIMIT 12",$group_id));$backup=wp_nonce_url(admin_url('admin-post.php?action=rallyop_download_backup&group_id='.$group_id),'rallyop_backup_'.$group_id);?>
    <section class="rop-safety-panel" data-rop-safety><div><span>OWNER TOOLS</span><h3>Admin safeguards</h3><p>Changes are logged, deleted games remain recoverable, and new entries are checked for duplicates.</p><a class="rop-backup" href="<?php echo esc_url($backup); ?>">DOWNLOAD GAME BACKUP</a></div><div><h4>Recovery</h4><?php if(!$trash):?><p>No deleted games waiting.</p><?php else:foreach($trash as $item):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="rallyop_restore_game"><input type="hidden" name="trash_id" value="<?php echo (int)$item->id; ?>"><?php wp_nonce_field('rallyop_restore_game_'.$item->id);?><span>Game #<?php echo (int)$item->game_id; ?> · <?php echo esc_html(wp_date('M j, g:i a',strtotime($item->deleted_at)));?></span><button>RESTORE</button></form><?php endforeach;endif;?></div><div><h4>Edit history</h4><?php if(!$audit):?><p>No changes recorded yet.</p><?php else:foreach($audit as $event):?><p><b><?php echo esc_html(strtoupper($event->action));?></b> Game #<?php echo (int)$event->game_id;?> · <?php echo esc_html(wp_date('M j, g:i a',strtotime($event->created_at)));?></p><?php endforeach;endif;?></div></section>
    <?php
}, 205);

