d.dataset.opponentWhy=value+' earned Giant Killer by beating:\n• '+best+'\nThat team entered with the higher average rating.';}});}document.addEventListener('click',function(e){if(e.target.closest('.rop-highlights-launch,[data-rop-highlights-nav]'))setTimeout(enrich,80);var card=e.target.closest('.rop-badge');if(card)setTimeout(function(){var why=card.querySelector('.rop-badge-why');if(why&&card.dataset.opponentWhy)why.textContent=card.dataset.opponentWhy;},0);});})();
