    $highlight_why = <<<'JS'
(function(){
  function games(){return Array.from(document.querySelectorAll('.rop-game-date')).map(function(d){var row=d.closest('tr'),teams=row&&row.querySelectorAll('.rop-game-team');if(!teams||teams.length!==2)return null;function side(t){var score=t.querySelector('span'),nums=score?(score.textContent.match(/\d+/g)||[]):[];return{names:(t.querySelector('strong')?t.querySelector('strong').textContent:'').split('&').map(function(n){return n.trim();}).filter(Boolean),score:parseInt(nums[nums.length-1]||0,10),won:t.classList.contains('winner')};}var label=d.textContent.trim(),parsed=Date.parse(label+' '+new Date().getFullYear());return{a:side(teams[0]),b:side(teams[1]),date:label,time:Number.isFinite(parsed)?parsed:Date.now()};}).filter(Boolean);}
  function why(card){var name=(card.querySelector('strong')||{}).textContent||'',weekly=card.classList.contains('rop-highlight-week'),cut=weekly?Date.now()-7*86400000:-Infinity,wins=0,losses=0,diff=0,opponents=[];games().filter(function(g){return g.time>=cut;}).forEach(function(g){var mine=g.a.names.indexOf(name)>=0?g.a:(g.b.names.indexOf(name)>=0?g.b:null);if(!mine)return;var other=mine===g.a?g.b:g.a;if(mine.won){wins++;opponents.push(g.date+' - beat '+other.names.join(' & ')+', '+mine.score+'-'+other.score);}else losses++;diff+=mine.score-other.score;});if(!wins&&!losses)return name+' will be explained here once recorded games qualify.';var title=weekly?'Player of the Week':'Player of the Day',reason=name+' earned '+title+' with '+wins+' win'+(wins===1?'':'s')+', '+losses+' loss'+(losses===1?'':'es')+', and a '+(diff>=0?'+':'')+diff+' point differential.';if(opponents.length)reason+='\n\nWins:\n- '+opponents.join('\n- ');reason+='\n\nTies are broken by point differential.';return reason;}
  function toggle(card){var open=card.getAttribute('aria-expanded')==='true',old=card.querySelector('.rop-highlight-why');card.setAttribute('aria-expanded',open?'false':'true');if(old)old.remove();if(!open){var detail=document.createElement('p');detail.className='rop-highlight-why';detail.textContent=why(card);card.appendChild(detail);}}
  function prepare(){document.querySelectorAll('.rop-highlight-hero').forEach(function(card){card.setAttribute('role','button');card.setAttribute('tabindex','0');card.setAttribute('aria-expanded','false');});document.querySelectorAll('.rop-badge').forEach(function(card){card.setAttribute('role','button');card.setAttribute('tabindex','0');if(!card.hasAttribute('aria-expanded'))card.setAttribute('aria-expanded','false');});}
  document.addEventListener('click',function(e){if(e.target.closest('.rop-highlights-launch,[data-rop-highlights-nav]')){setTimeout(prepare,60);return;}var hero=e.target.closest('.rop-highlight-hero');if(hero)toggle(hero);});
  document.addEventListener('keydown',function(e){var hero=e.target.closest&&e.target.closest('.rop-highlight-hero');if(hero&&(e.key==='Enter'||e.key===' ')){e.preventDefault();toggle(hero);}});
})();
JS;
    wp_add_inline_script('rallyop-sessions',$highlight_why);
    $badge_game_details = <<<'JS'
(function(){
  function games(){return Array.from(document.querySelectorAll('.rop-game-date')).map(function(d){var row=d.closest('tr'),teams=row&&row.querySelectorAll('.rop-game-team');if(!teams||teams.length!==2)return null;function side(t){var score=t.querySelector('span'),nums=score?(score.textContent.match(/\d+/g)||[]):[];return{names:(t.querySelector('strong')?t.querySelector('strong').textContent:'').split('&').map(function(n){return n.trim();}).filter(Boolean),score:parseInt(nums[nums.length-1]||0,10),won:t.classList.contains('winner')};}return{a:side(teams[0]),b:side(teams[1]),date:d.textContent.trim()};}).filter(Boolean);}
  function line(g,mine,other){return g.date+' - beat '+other.names.join(' & ')+', '+mine.score+'-'+other.score;}
  function enrich(){var all=games(),cards=Array.from(document.querySelectorAll('.rop-badge'));cards.forEach(function(card){var label=(card.querySelector('span')||{}).textContent||'',value=(card.querySelector('strong')||{}).textContent||'';if(label==='ON FIRE'&&value.toLowerCase().indexOf('not earned')<0){var player=value.split('·')[0].trim(),wins=[];for(var i=0;i<all.length;i++){var g=all[i],mine=g.a.names.indexOf(player)>=0?g.a:(g.b.names.indexOf(player)>=0?g.b:null);if(!mine)continue;if(!mine.won)break;var other=mine===g.a?g.b:g.a;wins.push(line(g,mine,other));}if(wins.length)card.dataset.opponentWhy=player+' is On Fire after:\n- '+wins.join('\n- ');}if(label==='GIANT KILLER'&&value.toLowerCase().indexOf('not earned')<0){var detail='';all.forEach(function(g){var win=g.a.won?g.a:g.b,lose=g.a.won?g.b:g.a,names=win.names.join(' & '),reverse=win.names.slice().reverse().join(' & ');if(!detail&&(value===names||value===reverse))detail=line(g,win,lose);});if(detail)card.dataset.opponentWhy=value+' earned Giant Killer:\n- '+detail+'\nThe defeated team entered with the higher average rating.';}});}
  document.addEventListener('click',function(e){if(e.target.closest('.rop-highlights-launch,[data-rop-highlights-nav]'))setTimeout(enrich,70);var card=e.target.closest('.rop-badge');if(card){enrich();setTimeout(function(){var why=card.querySelector('.rop-badge-why');if(why&&card.dataset.opponentWhy)why.textContent=card.dataset.opponentWhy;},0);}});
})();
JS;
    wp_add_inline_script('rallyop-sessions',$badge_game_details);
}, 210);
